// Spoken directions. Two kinds of voice:
//  - natural voices, generated by the server (/api/tts) and played as audio; they sound human on every phone
//    but need a connection and only speak English;
//  - the phone's own speech voices (speechSynthesis): offline, any language, quality depends on the phone.
// The choice is per device (phone voices differ between devices), kept in local storage as
// 'natural:<id>' | 'device:<voice name>' | 'device:auto'. A natural voice falls back to the phone's voice
// when it can't be fetched in time.

import { state, local } from './core.js';

export const NATURAL_VOICES = [
  { id: 'asteria', name: 'Asteria', note: 'American, female' },
  { id: 'luna', name: 'Luna', note: 'American, female' },
  { id: 'athena', name: 'Athena', note: 'British, female' },
  { id: 'orion', name: 'Orion', note: 'American, male' },
  { id: 'arcas', name: 'Arcas', note: 'American, male' },
  { id: 'helios', name: 'Helios', note: 'British, male' },
];

const FETCH_TIMEOUT_MS = 4000;
// A tenth of a second of silence, as a WAV file (8 kHz, 8-bit mono).
const SILENCE = (() => {
  const n = 800, b = new DataView(new ArrayBuffer(44 + n));
  const str = (o, t) => [...t].forEach((c, i) => b.setUint8(o + i, c.charCodeAt(0)));
  str(0, 'RIFF'); b.setUint32(4, 36 + n, true); str(8, 'WAVEfmt '); b.setUint32(16, 16, true); b.setUint16(20, 1, true);
  b.setUint16(22, 1, true); b.setUint32(24, 8000, true); b.setUint32(28, 8000, true); b.setUint16(32, 1, true); b.setUint16(34, 8, true);
  str(36, 'data'); b.setUint32(40, n, true);
  for (let i = 0; i < n; i++) b.setUint8(44 + i, 128);
  return typeof URL !== 'undefined' && typeof Blob !== 'undefined' ? URL.createObjectURL(new Blob([b], { type: 'audio/wav' })) : '';
})();

const englishPrompts = () => (navigator.language || 'en').toLowerCase().startsWith('en');

export function voiceChoice() {
  return local.get('voiceChoice') ?? (englishPrompts() ? `natural:${NATURAL_VOICES[0].id}` : 'device:auto');
}

export function setVoiceChoice(choice) {
  local.set('voiceChoice', choice);
}

// ---------- Natural voices ----------
let audio = null;
let latest = 0; // only the newest prompt plays; a slower, older one is dropped
const clips = new Map(); // text + voice -> object URL, so repeated prompts play at once

// iOS only lets audio play from a tap. Playing a moment of silence on the same element during a tap
// (Go, Preview, the sound button) lets later directions play without one.
export function unlockAudio() {
  audio ??= new Audio();
  if (!audio.paused) return;
  audio.src = SILENCE;
  audio.play().catch(() => {});
}

async function playNatural(text, id, ticket) {
  const key = `${id}\n${text}`;
  let url = clips.get(key);
  if (!url) {
    const ctl = new AbortController();
    const timer = setTimeout(() => ctl.abort(), FETCH_TIMEOUT_MS);
    try {
      const res = await fetch(`/api/tts?voice=${id}&text=${encodeURIComponent(text)}`, { signal: ctl.signal });
      if (!res.ok) throw new Error(`Voice unavailable (${res.status})`);
      url = URL.createObjectURL(await res.blob());
    } finally {
      clearTimeout(timer);
    }
    clips.set(key, url);
    if (clips.size > 60) {
      const [oldKey, oldUrl] = clips.entries().next().value;
      URL.revokeObjectURL(oldUrl);
      clips.delete(oldKey);
    }
  }
  if (ticket !== latest) return;
  audio ??= new Audio();
  audio.src = url;
  await audio.play();
}

// ---------- The phone's voices ----------
const QUALITY = /premium|enhanced|natural|neural|siri|wavenet|online/i;

// The phone's voices for the prompt language, best-sounding first.
export function deviceVoices() {
  if (!('speechSynthesis' in window)) return [];
  const lang = (englishPrompts() ? navigator.language || 'en-US' : navigator.language || 'en').toLowerCase();
  const base = lang.slice(0, 2);
  const score = (v) => {
    const l = v.lang.toLowerCase().replace('_', '-');
    let s = 0;
    if (l === lang) s += 4;
    if (QUALITY.test(v.name)) s += 6;
    if (/google/i.test(v.name)) s += 3; // Chrome's network voices sound far better than the built-in ones
    if (!v.localService) s += 1;
    if (v.default) s += 1;
    if (l.startsWith(base) && /^(samantha|karen|daniel|moira|tessa|alex|ava|evan|zoe|nathan)/i.test(v.name)) s += 1;
    return s;
  };
  return speechSynthesis
    .getVoices()
    .filter((v) => v.lang.toLowerCase().replace('_', '-').startsWith(base))
    .sort((a, b) => score(b) - score(a) || a.name.localeCompare(b.name));
}

export const isGoodDeviceVoice = (v) => QUALITY.test(v.name) || /google/i.test(v.name);

function speakDevice(text, name) {
  if (!('speechSynthesis' in window)) return;
  try {
    const voices = deviceVoices();
    const u = new SpeechSynthesisUtterance(text);
    const v = (name && name !== 'auto' && voices.find((x) => x.name === name)) || voices[0];
    if (v) u.voice = v;
    u.lang = v?.lang || (englishPrompts() ? navigator.language : 'en-US');
    u.rate = 1;
    speechSynthesis.cancel();
    speechSynthesis.speak(u);
  } catch {}
}

// Voice lists load late on some browsers; ask early so the first direction has them.
if (typeof window !== 'undefined' && 'speechSynthesis' in window) {
  speechSynthesis.getVoices();
  speechSynthesis.addEventListener?.('voiceschanged', () => speechSynthesis.getVoices());
}

// ---------- Speaking ----------
export function speak(text, { force = false, choice = voiceChoice() } = {}) {
  if (!text || (!state.settings.voice && !force)) return;
  const ticket = ++latest;
  audio?.pause();
  if ('speechSynthesis' in window) speechSynthesis.cancel();
  const [kind, id] = [choice.slice(0, choice.indexOf(':')), choice.slice(choice.indexOf(':') + 1)];
  if (kind === 'natural' && englishPrompts()) {
    unlockAudio(); // harmless outside a tap; inside one (Go, Preview) it keeps iOS happy
    playNatural(text, id, ticket).catch(() => ticket === latest && speakDevice(text, 'auto'));
  } else speakDevice(text, id);
}
